import{_ as a,o as t,c as o,a4 as r}from"./chunks/framework.Cf9VNWP6.js";const g=JSON.parse('{"title":"Maintenance & Release Guide","description":"","frontmatter":{},"headers":[],"relativePath":"MAINTENANCE.md","filePath":"MAINTENANCE.md"}'),i={name:"MAINTENANCE.md"};function n(l,e,s,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="maintenance-release-guide" tabindex="-1">Maintenance &amp; Release Guide <a class="header-anchor" href="#maintenance-release-guide" aria-label="Permalink to “Maintenance &amp; Release Guide”">​</a></h1><p>This document describes the technical process for maintaining and releasing <code>@chitrank2050/ask-widget</code>.</p><h2 id="release-workflow" tabindex="-1">Release Workflow <a class="header-anchor" href="#release-workflow" aria-label="Permalink to “Release Workflow”">​</a></h2><p>We use <strong><a href="https://github.com/chitranklabs/git-hygiene" target="_blank" rel="noreferrer">git-hygiene</a></strong> to automate versioning, changelog generation, and npm releases.</p><h3 id="_1-development-the-commit" tabindex="-1">1. Development (The &quot;Commit&quot;) <a class="header-anchor" href="#_1-development-the-commit" aria-label="Permalink to “1. Development (The &quot;Commit&quot;)”">​</a></h3><p>Every commit must follow the <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> standard. This is enforced locally via <strong>Lefthook</strong> and in CI. The commit message determines the next version bump (major, minor, or patch).</p><h3 id="_2-phase-1-prepare-release-pr" tabindex="-1">2. Phase 1: Prepare (Release PR) <a class="header-anchor" href="#_2-phase-1-prepare-release-pr" aria-label="Permalink to “2. Phase 1: Prepare (Release PR)”">​</a></h3><p>To start a release, manually trigger the <strong><code>Release 1 - Prepare PR</code></strong> workflow from the GitHub Actions tab.</p><ul><li>It calculates the recommended version bump using <code>git-hygiene</code>.</li><li>It updates <code>package.json</code> and <code>CHANGELOG.md</code>.</li><li>It opens a Pull Request for review.</li></ul><h3 id="_3-phase-2-finalize-publishing" tabindex="-1">3. Phase 2: Finalize (Publishing) <a class="header-anchor" href="#_3-phase-2-finalize-publishing" aria-label="Permalink to “3. Phase 2: Finalize (Publishing)”">​</a></h3><p>When the Release PR is merged into <code>main</code>:</p><ol><li>The <strong><code>Release 2 - Finalize Tag</code></strong> workflow triggers automatically.</li><li>It tags the commit with the new version (e.g., <code>v0.6.0</code>).</li><li>It creates a GitHub Release with the changelog.</li><li>It builds the library and publishes it to <strong>NPM</strong>.</li><li>It generates SLSA Build Provenance for security.</li><li>It redeploys the Documentation site.</li></ol><hr><h2 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to “Infrastructure”">​</a></h2><ul><li><strong>CI/CD:</strong> <code>.github/workflows/</code></li><li><strong>Bot Setup:</strong> <code>.github/actions/setup-bot/</code></li><li><strong>Hook Manager:</strong> <code>lefthook.yml</code></li><li><strong>Changelog Config:</strong> <code>cliff.toml</code></li></ul>',15)])])}const p=a(i,[["render",n]]);export{g as __pageData,p as default};
